// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));

        uint256 fund = 1 ether;
        vm.deal(address(this), fund);
        (bool s, ) = address(c).call{value: fund}("");
        require(s);

        bool ok;
        vm.prank(caller);
        try c.withdrawAll(address(0xBEEF)) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == (caller == address(this)));
    }
}
